export const ALL_CONTRACTS: readonly ContractDescriptor[] = [
  EXECUTION_PROFILE_CONTRACT,
  EFFECTIVE_CONTEXT_CONTRACT,
  CANDIDATE_TRANSACTION_CONTRACT,
  SOURCE_USE_PLAN_CONTRACT,
  REPAIR_CONTRACT,
  REVIEW_CONTRACT,
  ROUTE_CONTRACT,
  ATTEMPT_EVIDENCE_CONTRACT,
  WORKER_REPORT_CONTRACT,
  READER_EXPERIENCE_REVIEW_CONTRACT,
  SOURCE_INTEGRITY_REVIEW_CONTRACT,
  QUIZ_INTEGRITY_RESULT_CONTRACT,
  AGGREGATED_CHAPTER_REVIEW_CONTRACT,
  JUDGE_CAPABILITY_QUALIFICATION_CONTRACT,
  REVIEW_EVIDENCE_ENVELOPE_CONTRACT,
  REVIEW_MODEL_OUTPUT_V2_CONTRACT,
  EMISSION_PACKAGE_CONTRACT,
];

export type ContractManifest = {
  schema: "contract-manifest-v1";
  frozenAtIso: string;
  contracts: Array<{ name: string; version: number; ownerPrompt: string; hash: string }>;
};

export function computeContractManifest(frozenAtIso: string): ContractManifest {
  return {
    schema: "contract-manifest-v1",
    frozenAtIso,
    contracts: ALL_CONTRACTS.map((c) => ({
      name: c.name,
      version: c.version,
      ownerPrompt: c.ownerPrompt,
      hash: contractHash(c),
    })).sort((a, b) => (a.name < b.name ? -1 : a.name > b.name ? 1 : 0)), // byte-wise: locale-independent
  };
}

const __dirname = dirname(fileURLToPath(import.meta.url));

export const CONTRACT_MANIFEST_PATH = resolve(__dirname, "contract-manifest.json");

export function loadFrozenManifest(path = CONTRACT_MANIFEST_PATH): ContractManifest {
  return JSON.parse(readFileSync(path, "utf8")) as ContractManifest;
}

/** Compare live descriptors against the frozen manifest. Returns human-readable
 *  divergences; [] = frozen state holds. Consumed by the freeze test AND by any
 *  package that must "verify the Phase 0 contract manifest before editing". */
export function contractFreezeDivergences(manifest = loadFrozenManifest()): string[] {
  const problems: string[] = [];
  const live = new Map(ALL_CONTRACTS.map((c) => [c.name, c]));
  const frozen = new Map(manifest.contracts.map((c) => [c.name, c]));
  for (const [name, c] of live) {
    const f = frozen.get(name);
    if (!f) { problems.push(`contract "${name}" is live but missing from the frozen manifest`); continue; }
    if (f.version !== c.version) problems.push(`contract "${name}" version drift: frozen v${f.version} vs live v${c.version}`);
    const h = contractHash(c);
    if (f.hash !== h) problems.push(`contract "${name}" hash drift: frozen ${f.hash.slice(0, 12)}… vs live ${h.slice(0, 12)}… (bump version + regenerate manifest + integration review)`);
  }
  for (const name of frozen.keys()) {
    if (!live.has(name)) problems.push(`contract "${name}" is frozen but no longer defined`);
  }
  return problems;
}

